\begin{tikzpicture}[x=10mm,y=10mm,draw=black,text=black,line cap=round,line join=round,>=stealth,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{maximumTwoRed}{HTML}{EF6068}
\definecolor{maximumThreeBlue}{HTML}{268CFF}
\path[use as bounding box] (-1.8,-3.85) rectangle (4.1,3.1);
\draw[black,line width=0.5pt,->] (-1.5,0)--(3.65,0);
\draw[black,line width=0.5pt,->] (0,-2.5)--(0,2.75);
\foreach \v in {1,2,3}{\draw[black,line width=0.4pt] (\v,0)--(\v,0.12);\node[anchor=north,yshift=-2pt,inner sep=1pt] at (\v,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {-2,-1,1,2}{\draw[black,line width=0.4pt] (0,\v)--(0.12,\v);\node[anchor=east,xshift=-3pt,inner sep=1pt] at (0,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \px/\py in {0/-2,1/-1,2/0,1/1,0/2}{\fill[maximumTwoRed] (\px,\py) circle[radius=1.6pt];}
\foreach \px/\py in {1/-2,2/-1,2/1,1/2}{\fill[maximumThreeBlue] (\px,\py) circle[radius=1.6pt];}
\node[anchor=north west,yshift=-3pt,inner sep=1pt] at (3.65,0) {$x$};
\node[anchor=south east,xshift=-3pt,inner sep=1pt] at (0,2.75) {$y$};
\fill[maximumTwoRed] (-0.6,-2.95) circle[radius=1.6pt];
\node[anchor=west,inner sep=1pt] at (-0.3,-2.95) {maximum $2$};
\fill[maximumThreeBlue] (-0.6,-3.5) circle[radius=1.6pt];
\node[anchor=west,inner sep=1pt] at (-0.3,-3.5) {maximum $3$};
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[{"name":"relationBlue","hex":"268CFF","reason":"Identifies the two continuous branches and their included common vertex."}],"reference":"Source PDF page 8 Q47(d); answer PDF page 10, printed page 588, p8-q47-d-answer-graph"}
\begin{tikzpicture}[x=16mm,y=16mm,draw=black,text=black,line cap=round,line join=round,>=stealth,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{relationBlue}{HTML}{268CFF}
% Drawing coordinates are X=x/t and Y=y/t, with t>0.
\path[use as bounding box] (-1.7,-2.05) rectangle (2.3,2.2);
\draw[black,line width=0.5pt,->] (-1.5,0)--(2,0);
\draw[black,line width=0.5pt,->] (0,-1.85)--(0,1.85);
\draw[black,line width=0.4pt] (1,0)--(1,0.07);
\draw[black,line width=0.4pt] (0,1)--(0.07,1);
\draw[black,line width=0.4pt] (0,-1)--(0.07,-1);
\draw[relationBlue,line width=0.8pt,<-] plot[domain=-0.7:1,samples=2] (\x,{1-\x});
\draw[relationBlue,line width=0.8pt,<-] plot[domain=-0.7:1,samples=2] (\x,{\x-1});
\fill[relationBlue] (1,0) circle[radius=1.7pt];
\node[anchor=north west,xshift=2pt,yshift=-3pt,inner sep=1pt] at (1,0) {$t$};
\node[anchor=south west,xshift=2pt,yshift=2pt,inner sep=1pt] at (0,1) {$t$};
\node[anchor=north west,xshift=2pt,yshift=-2pt,inner sep=1pt] at (0,-1) {$-t$};
\node[anchor=north west,yshift=-3pt,inner sep=1pt] at (2,0) {$x$};
\node[anchor=south east,xshift=-3pt,inner sep=1pt] at (0,1.85) {$y$};
\end{tikzpicture}
